import{_ as n,C as r,o as a,c as o,E as i,a2 as s}from"./chunks/framework.Cm6XCzck.js";const f=JSON.parse('{"title":"等待应该是运行时状态，而不是智能体循环","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"等待应该是运行时状态，而不是智能体循环","date":"2026-08-19","column":"digital-employee","category":"academic","article_type":"technical-analysis","edition":"research-center","research_question":"SentinelBench 对长时间监控智能体究竟支持什么架构结论：可靠等待主要是模型能力、轮询策略，还是应该从持续推理和动作中分离出来的运行时状态？","summary":"SentinelBench 提供了一手实验依据，说明监控是一类独立的智能体工作负载：条件感知等待可以在长时间等待中显著降低成本并改善完成率，但生产级监控仍需要持久条件状态、明确准入以及独立核验的外部效果证据。","sources":"arXiv:2606.05342v2; Microsoft Research SentinelBench article; microsoft/sentinel_environments @ 0faca33cc58ea62e97a928b67cd3beec7176b408; research/reading/Q-20260804-11-sentinelbench-monitoring.md; research/analysis/Q-20260804-11-sentinelbench-monitoring.md","cover":"/assets/covers/academic-sentinelbench-waiting-runtime-v2.png"},"headers":[],"relativePath":"zh/digital-employee/2026-08-19-sentinelbench-waiting-runtime.md","filePath":"zh/digital-employee/2026-08-19-sentinelbench-waiting-runtime.md","lastUpdated":1787382334000}'),l={name:"zh/digital-employee/2026-08-19-sentinelbench-waiting-runtime.md"};function c(h,e,d,p,g,m){const t=r("ArticleCover");return a(),o("div",null,[i(t,{image:"/assets/covers/academic-sentinelbench-waiting-runtime-v2.png",kicker:"数字员工 · Academic Observation 004",title:"等待应该是运行时状态",summary:"监控智能体应该独立保存“正在等待什么”，而不是把它寄存在某一次恰好醒着的模型对话里。",version:"DA004",status:"Academic Runtime V5 · 2026-08-19",languageHref:"/en/digital-employee/2026-08-19-sentinelbench-waiting-runtime",languageLabel:"English"}),e[0]||(e[0]=s('<h1 id="等待应该是运行时状态-而不是智能体循环" tabindex="-1">等待应该是运行时状态，而不是智能体循环 <a class="header-anchor" href="#等待应该是运行时状态-而不是智能体循环" aria-label="Permalink to &quot;等待应该是运行时状态，而不是智能体循环&quot;">​</a></h1><p>有些智能体任务因为做得太少而失败。监控任务却可能因为<strong>做得太多</strong>而失败。</p><p>如果要求是“有票时告诉我”“再出现 3 条未读消息时提醒我”或“价格越过阈值时执行动作”，更频繁地刷新页面并不会让外部事件更早发生。模型持续推理、点击和轮询，可能只是消耗更多令牌、制造更多操作失败机会，最后还可能在条件真正出现前自行放弃。</p><p>Microsoft Research 在 2026 年发布的 <strong>SentinelBench</strong> 正好把这个问题变成了可测量对象。它研究的重点不是单纯让智能体“想得更久”，而是把<strong>等待本身</strong>作为工作负载。基准包含 100 个任务、10 个合成网页环境，环境状态会独立于智能体动作发生变化；评估不仅看任务是否完成，还看目标事件出现后的反应时间，以及推理和工具消耗。论文与代码分别公开在 <a href="https://arxiv.org/abs/2606.05342" target="_blank" rel="noreferrer">arXiv:2606.05342v2</a> 和 <a href="https://github.com/microsoft/sentinel_environments" target="_blank" rel="noreferrer">Microsoft 的 sentinel_environments 仓库</a>。</p><p>这些证据支持一个有边界的工程判断：<strong>监控中的“等待”应该成为运行时状态，而不应临时拼成一串自由形式的智能体回合。</strong> SentinelBench 并没有证明某种生产级监控架构，但它把缺失的运行时边界暴露得非常清楚。</p><h2 id="监控不只是-一个很长的任务" tabindex="-1">监控不只是“一个很长的任务” <a class="header-anchor" href="#监控不只是-一个很长的任务" aria-label="Permalink to &quot;监控不只是“一个很长的任务”&quot;">​</a></h2><p>普通长链路智能体评测通常默认：要继续前进，智能体就要做点什么——打开应用、读取状态、选择工具、改变环境，然后继续下一步。</p><p>SentinelBench 有意打破这个假设。场景开始后，预设事件会独立更新数据库和网页界面。智能体可能需要等待新邮件、新职位、股票价格变化、日历邀请或其他由外部世界触发的事件。于是问题不再只是“下一步做什么”，还多了一个更基础的问题：<strong>现在到底该不该做任何事？</strong></p><p>根据<a href="https://arxiv.org/html/2606.05342v2" target="_blank" rel="noreferrer">论文正文</a>，100 个任务中有 20 个“无操作”任务，其余任务同时覆盖主动/被动监控，以及绝对/相对条件。这些分类不是装饰。</p><p>被动任务主要要求检测条件已经成立；主动任务可能还需要打开会话、查看隐藏信息，或者在检测后改变应用状态。绝对条件往往只看当前状态即可判断；相对条件，例如“比现在再多 3 条未读提醒”，必须保存一个起始基线，之后才能计算变化量。</p><p>“无操作”任务尤其重要。在这些任务里，目标条件从来不会发生。正确行为是持续监控到时间窗口结束，而不是为了“交差”虚构一个成功事件。它把很多普通智能体基准很少测试的一类错误明确了出来：<strong>过早宣称完成，本身就是失败。</strong></p><h2 id="评测把-做过什么-和-结果是否正确-分开了" tabindex="-1">评测把“做过什么”和“结果是否正确”分开了 <a class="header-anchor" href="#评测把-做过什么-和-结果是否正确-分开了" aria-label="Permalink to &quot;评测把“做过什么”和“结果是否正确”分开了&quot;">​</a></h2><p>SentinelBench 的公开评测工具并不是看智能体最后说得像不像成功。每个场景都包含用于检查最终数据库状态的查询，同时服务器记录智能体何时相对于目标条件发出完成信号。<a href="https://github.com/microsoft/sentinel_environments" target="_blank" rel="noreferrer">仓库 README</a> 明确说明，普通任务要同时满足场景状态检查为真，并且完成信号发生在条件时间之后；无操作任务则要求根本不能提前发出完成信号。</p><p>这种做法有一个很实际的意义：<strong>发现条件和完成效果不是一回事。</strong></p><p>智能体可能正确发现了一个符合要求的新职位，却没有真正申请；可能看到了邮件，却在条件还没完整满足前就通知用户；也可能在监控窗口尚未结束时，很自信地说“没有发现”。很长的操作轨迹可以显得十分勤奋，但业务结果仍然是错的。</p><p>因此，对监控系统更稳妥的评估原则应该是：<strong>工作活动只是过程证据，不是完成证明。</strong> 外部条件是否成立，以及随后要求的外部动作是否真正发生，都需要各自的证据。</p><h2 id="wait-for-改变的是-等待工作放在哪里" tabindex="-1"><code>wait_for</code> 改变的是“等待工作放在哪里” <a class="header-anchor" href="#wait-for-改变的是-等待工作放在哪里" aria-label="Permalink to &quot;`wait_for` 改变的是“等待工作放在哪里”&quot;">​</a></h2><p>论文比较了两种浏览器智能体配置。第一种给智能体普通的 <code>sleep(time)</code> 工具，第二种给它专门的 <code>wait_for(condition, timeout)</code> 工具。</p><p>重要的并不是哪个函数名更先进，而是<strong>监控状态由谁保存</strong>。</p><p>使用 <code>sleep</code> 时，模型决定睡多久；醒来后重新观察页面、再次推理，再决定是否继续睡。要等待的条件很大程度仍然埋在整个智能体轨迹里。</p><p>使用论文中的 <code>wait_for</code> 时，条件和超时时间被明确作为工具参数。这个原型先保存页面文本基线，再检查后续页面差异；已经评估过的变化不会重复交给模型；模型判断被限频；页面会周期性刷新；超时前还会做一次最终检查。论文附录 D 还公开了退避参数，因此这里不是一句抽象的“事件驱动”口号，而是可以检查的具体实现。</p><p>这个实现本质上仍然包含轮询。它不是 Webhook，也不是持久事件流，更不是生产级通知服务。但从架构上，它已经把自由运行的智能体循环经常混在一起的三个问题拆开了：</p><ul><li><strong>条件状态</strong>：究竟在等什么；</li><li><strong>观察策略</strong>：怎样采样外部环境；</li><li><strong>模型调用</strong>：什么时候出现了足够新的证据，值得再次让模型判断。</li></ul><p>一旦这三层分离，观察机制就可以变化，而用户意图不需要重写。网页差异、数据库监听、服务商 Webhook 或事件流，原则上都可以服务于同一个更高层的条件合同。</p><h2 id="基线结果说明的是权衡-不是一条定律" tabindex="-1">基线结果说明的是权衡，不是一条定律 <a class="header-anchor" href="#基线结果说明的是权衡-不是一条定律" aria-label="Permalink to &quot;基线结果说明的是权衡，不是一条定律&quot;">​</a></h2><p>论文的结果有价值，恰恰因为它并没有得出“条件等待在所有指标上都更好”这种简单结论。下面这些数字都是作者在受控基准上的<strong>来源陈述研究结果</strong>；本次 Academic 运行没有发现完整复现这些基线结果的独立第三方证据。</p><p>在默认时长下，论文报告 GPT-5.4 使用 <code>wait_for</code> 的整体成功率为 <strong>0.75</strong>，使用 <code>sleep</code> 为 <strong>0.68</strong>。单任务 API 成本中位数分别为 <strong>0.23 美元</strong>和 <strong>1.17 美元</strong>；工具调用次数中位数分别为 <strong>6 次</strong>和 <strong>19.5 次</strong>。</p><p>把 <code>speed_factor</code> 降到 0.25 后，单个任务最长可接近 40 分钟，成本差异更明显。作者报告 <code>wait_for</code> 成功完成 <strong>69 个任务</strong>，<code>sleep</code> 完成 <strong>56 个任务</strong>；API 成本中位数分别为 <strong>0.48 美元</strong>与 <strong>4.65 美元</strong>，后者约为前者的 9.7 倍。</p><p>但反应速度并不是同方向。在这个 GPT-5.4 长时实验里，反应时间中位数是 <code>wait_for</code> <strong>54.8 秒</strong>，<code>sleep</code> <strong>38.9 秒</strong>。默认时长下的 GPT-5.4 结果也有类似现象：<code>wait_for</code> 成本更低、完成更多任务，但反应时间中位数略慢。</p><p>这不是基准的缺点，反而说明监控质量本来就不是一个单一分数。至少需要同时看：</p><ul><li>完成可靠性；</li><li>过早成功与漏检风险；</li><li>反应延迟；</li><li>推理与工具成本；</li><li>后续外部动作是否正确。</li></ul><p>5 秒轮询一次可能反应快，但成本高；退避过度的监控可能便宜，却错过短暂机会。生产运行时需要针对具体任务定义服务目标，而不是给所有监控任务套一个固定频率。</p><h2 id="生产监控至少需要四个边界" tabindex="-1">生产监控至少需要四个边界 <a class="header-anchor" href="#生产监控至少需要四个边界" aria-label="Permalink to &quot;生产监控至少需要四个边界&quot;">​</a></h2><p>下面的四层不是 SentinelBench 论文提出的正式合同，而是 Research Center 基于论文、公开实现和作者明确局限所做的综合判断。</p><table tabindex="0"><thead><tr><th>边界</th><th>运行时要回答的问题</th><th>需要保存的证据</th></tr></thead><tbody><tr><td><strong>条件状态</strong></td><td>到底在等什么？</td><td>稳定监控 ID、条件、基线/参考状态、作用范围、到期时间</td></tr><tr><td><strong>观察策略</strong></td><td>怎样发现变化？</td><td>数据源、观察机制、频率/退避、延迟目标、成本与限流预算</td></tr><tr><td><strong>条件准入</strong></td><td>证据是否足够支持继续执行？</td><td>当前观察、条件判断、不确定性、是否被授权进入下一步</td></tr><tr><td><strong>效果证据</strong></td><td>通知或动作真的发生了吗？</td><td>外部接收结果、动作/通知 ID、去重状态、最终结果</td></tr></tbody></table><p>为什么要拆成四层？因为它们的失败方式完全不同。</p><p>进程重启后可能丢掉起始基线，但网页观察器本身仍然正常；页面可能发生变化，却并不满足用户真正的条件；条件判断可能是对的，但通知没有真正送达；外部动作可能成功了两次，因为运行时忘记自己已经处理过同一次条件出现。</p><p>如果所有这些都只叫“智能体正在监控”，故障位置就被隐藏了。把它们变成独立的运行时状态，恢复和审计才有准确对象。</p><h3 id="相对条件让-持久状态-不可回避" tabindex="-1">相对条件让“持久状态”不可回避 <a class="header-anchor" href="#相对条件让-持久状态-不可回避" aria-label="Permalink to &quot;相对条件让“持久状态”不可回避&quot;">​</a></h3><p>SentinelBench 的相对任务对此说明得很直接。“达到 100 个赞时提醒我”可以只看一个当前快照；“再增加 100 个赞时提醒我”必须知道监控开始时是多少。</p><p>如果这个基线只存在于临时模型上下文里，一次进程崩溃、上下文重置甚至错误摘要，都可能悄悄改变任务含义。生产监控因此需要独立于模型回合的持久条件身份和参考状态。</p><h3 id="什么都没发生-也应该有正式终态" tabindex="-1">“什么都没发生”也应该有正式终态 <a class="header-anchor" href="#什么都没发生-也应该有正式终态" aria-label="Permalink to &quot;“什么都没发生”也应该有正式终态&quot;">​</a></h3><p>无操作任务并不是“没有工作所以失败”，而是“在受治理窗口内条件没有出现，因此没有任何后续动作获得授权”。</p><p>这在运行时里应该成为明确结果，例如“条件未满足”或“监控到期”，而不是逼着智能体为了产出一个传统意义的成功答复，虚构某个事件已经发生。</p><h3 id="检测成功不等于交付成功" tabindex="-1">检测成功不等于交付成功 <a class="header-anchor" href="#检测成功不等于交付成功" aria-label="Permalink to &quot;检测成功不等于交付成功&quot;">​</a></h3><p>SentinelBench 用数据库状态评估外部动作，也提示了另一个关键边界：<strong>检测到条件，不等于外部效果已经完成。</strong></p><p>监控器看到条件成立之后，还不能证明消息已经送达、订单已经被接收、工单已经创建，或业务记录已经落到正确系统。涉及后果的监控任务，应当为外部效果建立独立身份，并保存接收或状态核验证据。</p><h2 id="这些证据还没有覆盖什么" tabindex="-1">这些证据还没有覆盖什么 <a class="header-anchor" href="#这些证据还没有覆盖什么" aria-label="Permalink to &quot;这些证据还没有覆盖什么&quot;">​</a></h2><p>论文对自己的边界相当明确。</p><p>事件时间是人工构造的，目标时间来自受控模拟，并不代表真实服务中的事件分布。十个网页环境是轻量级合成仿真，并非生产网站；作者也明确指出，走到未充分测试的交互路径时仍可能暴露环境错误或功能缺口。</p><p>大部分成功条件仍然是客观条件。像“出现紧急缺陷时告诉我”这种需要主观判断的条件还没有充分覆盖。现有大部分条件一旦成立就会持续存在；只短暂出现、错过后就永远失效的条件，被论文列为更困难的后续方向。</p><p>被评测的 <code>wait_for</code> 也只是基于页面文本差异和周期刷新实现的原型。SentinelBench 没有建立以下生产保证：进程崩溃后的安全恢复、通知或动作的仅一次语义、凭据续期、多监控任务之间的限流仲裁、同一条件多次发生时的身份区分，以及具有副作用动作的事务补偿。</p><p>还要保留一个证据原则：<strong>公开论文不等于独立验证。</strong> 论文、Microsoft Research 官方文章和开源仓库提供了清晰来源、可检查实现和可复现实验包，但它们本身仍属于研究作者及其机构的一手材料。本次运行没有发现完整独立复现。</p><h2 id="下一步最值得测什么" tabindex="-1">下一步最值得测什么？ <a class="header-anchor" href="#下一步最值得测什么" aria-label="Permalink to &quot;下一步最值得测什么？&quot;">​</a></h2><p>下一轮实验不应该只是把 <code>sleep</code> 时间再拉长。</p><p>更接近生产的问题是：在监控过程中强制中断进程，再重启 Worker，看看能否恢复同一个条件身份和同一个基线，并且不重复执行已经发生过的外部动作；加入只短暂存在的条件，检测延迟会直接决定能否完成；加入主观条件，让“条件准入”必须保存可审计证据；让许多监控器共享相同凭据和限流预算；同时比较网页轮询与服务商原生事件，而保持上层条件合同和效果合同不变。</p><p>这些实验才能回答 SentinelBench 有意没有回答的问题：条件感知等待在受控基准里的优势，能否跨过真实长时间运行时的恢复、身份和副作用边界？</p><p>现有证据已经足够支持一个更窄、也更适合工程实现的变化：<strong>智能体不应该为了继续等待而必须继续思考。</strong> 条件、观察策略和完成证据应该留在运行时里；模型只有在出现新证据或需要做受治理判断时才被重新调用。</p><p>这比“事件驱动智能体解决了监控”保守得多，但也更容易真正写成可靠系统。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><ol><li>Matheus Kunzler Maldaner 等，<strong>SentinelBench: A Benchmark for Long-Running Monitoring Agents</strong>，arXiv:2606.05342v2，2026-06-05 — <a href="https://arxiv.org/abs/2606.05342" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.05342</a></li><li>论文 HTML 全文 — <a href="https://arxiv.org/html/2606.05342v2" target="_blank" rel="noreferrer">https://arxiv.org/html/2606.05342v2</a></li><li>Microsoft Research，<strong>SentinelBench, a Benchmark for Long-Running Monitoring Agents</strong>，2026-06-08 — <a href="https://www.microsoft.com/en-us/research/articles/sentinelbench-a-benchmark-for-long-running-monitoring-agents/" target="_blank" rel="noreferrer">https://www.microsoft.com/en-us/research/articles/sentinelbench-a-benchmark-for-long-running-monitoring-agents/</a></li><li>Microsoft，<strong>sentinel_environments</strong>，本次检查固定到提交 <code>0faca33cc58ea62e97a928b67cd3beec7176b408</code> — <a href="https://github.com/microsoft/sentinel_environments" target="_blank" rel="noreferrer">https://github.com/microsoft/sentinel_environments</a></li><li>受治理 Deep Reading — <code>research/reading/Q-20260804-11-sentinelbench-monitoring.md</code></li><li>受治理 Research Analysis — <code>research/analysis/Q-20260804-11-sentinelbench-monitoring.md</code></li></ol><p>**证据边界：**第 1–4 项属于论文作者的一手论文、官方研究文章和第一方公开实现，可支持公开事实与来源陈述研究结果，但不构成独立复现。本文提出的四层监控边界明确属于 Research Center 基于这些证据形成的研究解释。</p>',62))])}const u=n(l,[["render",c]]);export{f as __pageData,u as default};
